import{z as n,x as i,o as r,c as B,q as t,j as E,D as e,d as o,s,S as p}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"残差连接与 DeepNet","description":"","frontmatter":{"title":"残差连接与 DeepNet","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/residual-scaling.md","filePath":"llm/residual-scaling.md","lastUpdated":1791413859000}'),N={name:"llm/residual-scaling.md"};function A(m,a,h,d,D,_){const l=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=t('<h1 id="残差连接与-deepnet" tabindex="-1">残差连接与 DeepNet <a class="header-anchor" href="#残差连接与-deepnet" aria-label="Permalink to &quot;残差连接与 DeepNet&quot;">​</a></h1><div class="epigraph"><p>把残差主干放大、把子层初始化缩小，Transformer 可以叠到上千层而不在训练初期散掉。</p><footer>—— Wang 等，DeepNet，2022</footer></div><p><a href="/llm/layernorm">上一课</a>对每个 token 的特征向量减均值、除标准差，再做逐维仿射；它稳定的是向量尺度，不自动解决深层残差的梯度衰减。缺口是主干与子层的增益配对：堆 \\(N\\) 层时，要么方差随深度涨，要么 Post-LN 把底层梯度压扁。Wang 等人 2022 年的 DeepNet 用 \\(\\alpha(N)\\) 缩放主干、\\(\\beta(N)\\) 缩小子层初始，使 Post-LN Transformer 可以到千层。本课写这套与深度挂钩的缩放，不重写 LN 的 \\(\\mu,\\sigma\\) 定义。它针对深度，不是宽度，也不是位置编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>堆 \\(N\\) 层时，若每层 \\(F_l\\) 在初始化附近输出与 \\(x\\) 同量级的噪声，残差和的方差会随 \\(N\\) 上涨；若 Post-LN 再把上涨压回去，雅可比又把底层梯度压小。<span class="marginnote">直觉类比：残差主干像一条会议主线，每个子层都在往里插话。一千层时若每个子层都大声嚷嚷（输出与主干同量级），主线立刻变成噪音现场；若每个子层都细若蚊蝇，底层永远得不到有效反馈。DeepNorm 的配对就是「把主线音量调大、把每个发言人的麦克风调小」，让插话始终是可听见的耳语。</span>Pre-LN 用单位主干避开切断，但主干范数可以随层累积，极深时仍可能数值溢出或把有效更新相对主干变得微不足道。</p><p>需要一种可分析的增益控制：让每一层对主干的改写是 \\(O(1/N)\\) 量级的小步，同时底层仍能收到足够梯度。He 等人的残差网络已经用「恒等映射为主」的直觉走过一遍；Transformer 的 \\(F\\) 含 softmax 与 FFN，初始化方差与深度的关系必须重写。DeepNet 的问题是给出一套与 \\(N\\) 挂钩的缩放，使 Post-LN Transformer 可以到千层，而不是劝所有人改用 Pre-LN。<span class="marginnote">深度病态有两种相反的脸：更新太大则散，更新相对主干太小则底层学不到。DeepNorm 同时做两件事——主干乘 \\(\\alpha\\gt 1\\) 以保住信号，子层初始乘小系数以限制每步改写。只做其中一件会偏到另一张脸上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DeepNorm 把 Post-LN 块写成</p> \\[x_{l+1}=\\mathrm{LN}\\bigl(\\alpha\\,x_l + G_l(x_l)\\bigr) \\]<p>其中 \\(G_l\\) 是注意力或 FFN 子层，\\(\\alpha\\) 随总层数 \\(N\\) 增大。子层参数在初始化时再按 \\(\\beta(N)\\) 缩小，使 \\(G_l\\) 起步时小于被放大的主干。编码器与解码器、自注意力与交叉注意力的 \\(\\alpha\\)、\\(\\beta\\) 公式在论文中分别给出，依赖于该侧的层数；工程上应使用原文的分组，而不是自造一个与 \\(N\\) 无关的全局常数。</p><p>训练不改变优化器种类，但深度上升后应配合适当的学习率，而不是沿用浅 Post-LN 的 warmup 却期望千层自己稳。Wang 等人在机器翻译与语言模型设定下把层数推到极深，展示损失可降、而不是只展示「能跑」。</p>',11)),(r(),E(p,null,{default:e(()=>[s(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B1%82%E8%BE%93%E5%85%A5%22%5D%20--%3E%20S%5B%22%E4%B9%98%E6%AE%8B%E5%B7%AE%E7%BC%A9%E6%94%BE%20alpha%22%5D%0A%20%20X%20--%3E%20G%5B%22%E5%AD%90%E5%B1%82%20G%20%E5%B0%8F%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20S%20--%3E%20A%5B%22%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20G%20--%3E%20A%0A%20%20A%20--%3E%20N%5B%22LayerNorm%22%5D%0A%20%20N%20--%3E%20Y%5B%22%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="残差分支的方差爆炸" tabindex="-1">残差分支的方差爆炸 <a class="header-anchor" href="#残差分支的方差爆炸" aria-label="Permalink to &quot;残差分支的方差爆炸&quot;">​</a></h3><p>初始化时把 \\(G_l\\) 看作近似线性的随机算子，输出方差与输入方差、参数方差成正比。无缩放的 \\(x+G(x)\\) 若每层都给主干加上不可忽略的噪声，经过 \\(N\\) 层后表示被随机游走过一次，LN 再强行拉回单位尺度，等于每层都在洗牌。<span class="marginnote">数字实例：设每层新增噪声方差与主干相同，方差逐层相加，\\(N\\) 层后方差约是单层的 \\(N\\) 倍——\\(N=1000\\) 时标准差约是单层的 \\(\\sqrt{1000}\\approx 32\\) 倍。尺度差 32 倍在半精度下已经接近溢出与归一化失真的边界，这就是「深层必炸」的量级来源，也是 \\(\\alpha\\)、\\(\\beta\\) 必须随 \\(N\\) 变的原因。</span>深层的有用梯度必须穿过一连串「加法 + 标准化」的病态雅可比。放大主干、缩小 \\(G\\)，是让加法项里 \\(x\\) 占主导，LN 几乎在归一一个已经很大的恒等项，雅可比接近「对主干友好」的极限。</p>',3)),(r(),E(p,null,{default:e(()=>[s(l,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E8%BE%93%E5%85%A5%E8%BF%87%20N%20%E5%B1%82%22%5D%20--%3E%20B%5B%22%E6%97%A0%E7%BC%A9%E6%94%BE%3A%20%E6%AF%8F%E5%B1%82%E5%8A%A0%E5%90%8C%E9%87%8F%E7%BA%A7%E5%99%AA%E5%A3%B0%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%96%B9%E5%B7%AE%E9%9A%8F%E5%B1%82%E6%95%B0%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20C%20--%3E%20D%5B%22Post-LN%20%E6%AF%8F%E5%B1%82%E5%BC%BA%E8%A1%8C%E6%8B%89%E5%9B%9E%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%BA%95%E5%B1%82%E6%A2%AF%E5%BA%A6%E8%A2%AB%E5%8E%8B%E6%89%81%20%E5%8D%83%E5%B1%82%E8%AE%AD%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20A%20--%3E%20F%5B%22DeepNorm%3A%20%E4%B8%BB%E5%B9%B2%E4%B9%98%20%CE%B1%20%E5%AD%90%E5%B1%82%E5%88%9D%E5%A7%8B%E4%B9%98%20%CE%B2%22%5D%0A%20%20F%20--%3E%20G%5B%22G(x)%20%E5%8F%AA%E6%98%AF%E4%B8%BB%E5%B9%B2%E7%9A%84%E5%B0%8F%E6%91%84%E5%8A%A8%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%81%92%E7%AD%89%E9%A1%B9%E4%B8%BB%E5%AF%BC%20LN%20%E8%BF%91%E4%BC%BC%E6%81%92%E7%AD%89%22%5D%0A%20%20H%20--%3E%20I%5B%22%E6%A2%AF%E5%BA%A6%E6%B2%BF%E4%B8%BB%E5%B9%B2%E5%9B%9E%E4%BC%A0%20%E5%8D%83%E5%B1%82%E5%8F%AF%E8%AE%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这与 Pre-LN 的单位通路不同：Pre-LN 的恒等不经过 LN；DeepNorm 的恒等经过 LN，但被 \\(\\alpha\\) 抬成主导项，LN 的局部线性接近缩放后的恒等，而不是接近「噪声与信号各一半」。</p><h3 id="deepnorm-的缩放与初始化" tabindex="-1">DeepNorm 的缩放与初始化 <a class="header-anchor" href="#deepnorm-的缩放与初始化" aria-label="Permalink to &quot;DeepNorm 的缩放与初始化&quot;">​</a></h3><p>\\(\\alpha(N)\\) 增大，残差流在进入 LN 前更像 \\(\\alpha x\\)，梯度回传到 \\(x\\) 时带有 \\(\\alpha\\) 再被 LN 的 \\(\\sigma\\) 除。\\(\\beta(N)\\) 缩小 \\(G\\) 的初始权重，使前向里 \\(G(x)\\) 相对 \\(\\alpha x\\) 是摄动。二者必须配对：只放大 \\(\\alpha\\) 而 \\(G\\) 仍按常规初始化，摄动仍可能与主干同阶；只缩小 \\(G\\) 而不放大主干，Post-LN 仍可能在深层把残差通路压扁。论文从更新范数的上界推导配对关系，而不是从网格搜索里偶然得到两个魔术数。</p><p><span class="marginnote">实现时最常见的错误是只在残差加法写了 \\(\\alpha\\)，却忘了按 \\(\\beta\\) 改初始化，或用预训练浅模型的权重直接塞进千层骨架。DeepNorm 是训练方案，不是把已有 48 层模型的残差乘一个常数就能变成 1000 层。</span></p><h3 id="千层-transformer-的工程含义" tabindex="-1">千层 Transformer 的工程含义 <a class="header-anchor" href="#千层-transformer-的工程含义" aria-label="Permalink to &quot;千层 Transformer 的工程含义&quot;">​</a></h3><p>能叠千层，不等于应当叠千层。参数与深度可以互换：同样参数，极深而窄的网络在并行上更难受，流水线切分、激活检查点、以及每层很小的有效更新都会让吞吐变差。<span class="marginnote">常见误区：参数量相同时「层数越多一定越聪明」。实际上同样 10 亿参数，摊到 1000 层每层就非常窄，张量并行的切分粒度变碎、流水线气泡变多、通信轮数变长，训练吞吐可能明显低于 100 层的宽模型。DeepNet 解决的是「能不能训」，不是「该不该训」；选深度仍要在吞吐与容量之间算账。</span>DeepNet 的价值是证明 Post-LN 的深度上限可以被缩放规则抬高，从而在「深度换宽度」的研究里有一条稳定基线。生产大模型仍多选中等深度加宽度、Pre-LN 与 RMSNorm，因为那条路的工具链更熟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DeepNorm 与 Pre-LN 不是互斥到不能讨论，但公式是为 Post-LN 写的。把 \\(\\alpha\\) 接到 Pre-LN 的 \\(x+F(\\mathrm{LN}(x))\\) 上会改变已有的单位通路，需要重新推导，不能抄编码器的 \\(\\alpha(N)\\)。它也不替代混合精度、梯度裁剪与合适的 \\(\\varepsilon\\)。</p><p>与并行 Attention-FFN 组合时，一层里两条 \\(G\\) 同时加到主干，摄动方差加倍，\\(\\beta\\) 可能需要再调。与 RoPE、ALiBi 无关：位置通道不进入 \\(\\alpha\\)。</p><p><span class="marginnote">原文的实验深度远大于当时主流翻译模型，但与后来的解码器千亿参数不是同一坐标系。引用 DeepNet 应强调「残差缩放使极深 Post-LN 可训」，而不是宣称千层已经是语言模型的最优深度。</span></p><h3 id="何时动残差增益" tabindex="-1">何时动残差增益 <a class="header-anchor" href="#何时动残差增益" aria-label="Permalink to &quot;何时动残差增益&quot;">​</a></h3><p>默认 Pre-LN 中等深度不必上 DeepNorm。当层数明显增加、Post-LN 梯度消失或初始化即 NaN、又希望保留每层 LN 输出时，再引入 \\(\\alpha\\) 与 \\(\\beta\\)。先加梯度裁剪与更小学习率，确认不是别的数值问题，再改残差定义，否则会把优化器问题写成架构问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>残差连接提供梯度近道，但深层需要对主干与子层的增益配对控制。</li><li>DeepNorm 在 Post-LN 中把主干乘 \\(\\alpha(N)\\)，并把子层初始化按 \\(\\beta(N)\\) 缩小。</li><li>目的是让每层对表示的改写保持小摄动，同时 LN 不切断主导的恒等项。</li><li>它使 Transformer 训练深度可以到千层量级，不自动成为参数分配的最优解。</li><li>公式依赖编码器/解码器层数，不能当与 \\(N\\) 无关的全局常数抄。</li><li>与 Pre-LN 默认栈正交：生产模型仍可不用 DeepNorm，只要深度与顺序匹配能力。</li><li>出处：Wang 等，<em>DeepNet: Scaling Transformers to 1,000 Layers</em>，2022；残差病态与 LN 位置见 Xiong 等（2020）；LayerNorm 见 Ba 等（2016）。</li></ul>',14))])}const P=n(N,[["render",A]]);export{L as __pageData,P as default};
